insert into public.exam_questions (id, module, question, options, answer, explanation) values
  (1, 'anatomia', 'Quale parte produce la lamina ungueale?', '["Il letto ungueale","La matrice","L''iponichio","L''eponichio"]'::jsonb, 1, 'La matrice è il tessuto vivo che produce la lamina; la lunula ne è la parte visibile.'),
  (2, 'anatomia', 'Cosa si rimuove durante la preparazione?', '["L''eponichio","La cuticola (pelle morta sulla lamina)","L''iponichio","Le pieghe laterali"]'::jsonb, 1, 'Si rimuove solo la cuticola morta; eponichio e iponichio sono tessuti vivi.'),
  (3, 'anatomia', 'Dove si trova il punto di stress?', '["Alla base, sotto la cuticola","Dove il bordo libero si stacca dal letto","Al centro della lunula","Sotto la matrice"]'::jsonb, 1, 'È la zona in cui il bordo libero lascia il letto: lì sopra va l''apex.'),
  (4, 'anatomia', 'Quanto cresce in media un''unghia della mano?', '["Circa 3 mm al mese","Circa 1 cm al mese","Circa 1 mm all''anno","Circa 365 mm all''anno"]'::jsonb, 0, 'Circa 0,1 mm al giorno, cioè 3 mm al mese.'),
  (5, 'anatomia', 'Una cliente ha un''unghia ispessita, giallastra e friabile. Cosa fai?', '["Copro con un gel coprente","Lavoro solo sulle altre dita","Rifiuto il servizio, disinfetto e la invio allo specialista","Limo via la parte malata"]'::jsonb, 2, 'Il sospetto di onicomicosi è una controindicazione assoluta.'),
  (6, 'anatomia', 'Una macchia verde sotto la ricostruzione indica di solito…', '["Muffa innocua","Un''infezione batterica (Pseudomonas)","Un colore difettoso","Una reazione alla lampada"]'::jsonb, 1, 'È un''infezione batterica: rimuovi il prodotto e invia al medico.'),
  (7, 'anatomia', 'Perché non si deve assottigliare la lamina naturale?', '["Perché diventa lucida","Perché isola meno dal calore e si indebolisce","Perché cresce più veloce","Non c''è nessun motivo"]'::jsonb, 1, 'Una lamina sottile espone a picchi di calore e danni.'),
  (8, 'igiene', 'Quale trattamento elimina anche le spore?', '["Sanificazione","Disinfezione","Sterilizzazione","Detersione"]'::jsonb, 2, 'Solo la sterilizzazione (autoclave) elimina ogni forma di vita.'),
  (9, 'igiene', 'Quale autoclave è adatta a strumenti cavi e porosi come le punte per fresa?', '["Classe N","Classe B","Qualsiasi forno","Sterilizzatrice a sfere"]'::jsonb, 1, 'L''autoclave di classe B (EN 13060) gestisce carichi cavi e porosi.'),
  (10, 'igiene', 'Quali guanti proteggono dai monomeri?', '["Lattice","Vinile","Nitrile","Cotone"]'::jsonb, 2, 'Il lattice non protegge dai monomeri: usa il nitrile.'),
  (11, 'igiene', 'Dal 1° settembre 2025 nell''UE è vietato nei cosmetici…', '["L''HEMA","Il TPO","L''acetone","L''EMA"]'::jsonb, 1, 'Il Reg. UE 2025/877 vieta TPO e DMTA, anche per uso professionale e per le scorte.'),
  (12, 'igiene', 'L''HEMA nei prodotti per unghie è…', '["Vietato del tutto","Libero per tutti","Ammesso solo per uso professionale con avvertenze","Ammesso solo nei top"]'::jsonb, 2, 'Reg. UE 2020/1682: uso professionale, con avvertenza sulle reazioni allergiche.'),
  (13, 'igiene', 'Quando è concreto il rischio di allergia agli acrilati?', '["Quando il prodotto polimerizzato è sulla lamina","Quando il prodotto non polimerizzato tocca la pelle","Solo con la lampada LED","Mai"]'::jsonb, 1, 'Il contatto della pelle con prodotto non polimerizzato sensibilizza.'),
  (14, 'igiene', 'In Italia la ricostruzione unghie in proprio richiede…', '["Solo un attestato privato","La qualifica di estetista e la SCIA","Nessun requisito","La partita IVA e basta"]'::jsonb, 1, 'Rientra nell''attività di estetista (L. 1/1990); l''apertura avviene con SCIA.'),
  (15, 'sistemi', 'Il gel monofasico…', '["Non ha bisogno di lampada","Fa da base, costruttore e sigillante","Si usa solo per il french","È un tipo di acrilico"]'::jsonb, 1, 'Un solo prodotto per tutte e tre le fasi.'),
  (16, 'sistemi', 'Come indurisce l''acrilico?', '["In lampada UV","All''aria, per reazione tra liquido e polvere","Con l''acetone","Con l''attivatore spray"]'::jsonb, 1, 'Monomero e polimero reagiscono all''aria.'),
  (17, 'sistemi', 'Una perla di acrilico troppo bagnata…', '["È la più resistente","Cola nei solchi e lascia monomero sulla pelle","È granulosa","Non aderisce"]'::jsonb, 1, 'Troppo liquido = colature, ritiro e rischio allergia.'),
  (18, 'sistemi', 'Il polygel si lavora con…', '["Monomero liquido","Slip solution e pennello, poi lampada","Acqua","Colla per tip"]'::jsonb, 1, 'Si modella con slip solution e indurisce in lampada.'),
  (19, 'sistemi', 'Il semipermanente…', '["Allunga l''unghia","Dà colore per 2–3 settimane ma non struttura","Si toglie solo con la fresa","Non va in lampada"]'::jsonb, 1, 'Colore su unghia naturale, nessuna struttura.'),
  (20, 'sistemi', 'Per scegliere la lampada conta soprattutto…', '["Il numero di watt","Il colore della lampada","L''abbinamento tra lunghezze d''onda e fotoiniziatori del gel","La marca"]'::jsonb, 2, 'Usa la lampada adatta al tuo sistema.'),
  (21, 'sistemi', 'Picco di emissione tipico di una lampada LED per unghie?', '["250 nm","365 nm soltanto","385–405 nm","500 nm"]'::jsonb, 2, 'I LED emettono intorno a 385–405 nm.'),
  (22, 'attrezzatura', 'Quale grana è la più abrasiva?', '["80","180","240","Buffer"]'::jsonb, 0, 'Numero più basso = grana più grossa.'),
  (23, 'attrezzatura', 'Quale grana usi sull''unghia naturale?', '["80–100","100/180","180–240","Carburo"]'::jsonb, 2, '180–240 per opacizzare senza assottigliare.'),
  (24, 'attrezzatura', 'Le punte in carburo si usano…', '["Sulla cuticola","Solo sul prodotto artificiale","Sull''unghia naturale","Per lucidare"]'::jsonb, 1, 'Sulla lamina naturale e sulla cuticola si usano punte diamantate.'),
  (25, 'attrezzatura', 'Velocità indicativa per lavorare in zona cuticolare?', '["5.000–10.000 RPM","20.000–25.000 RPM","30.000 RPM","Massima"]'::jsonb, 0, 'Velocità basse e pressione leggera vicino alla pelle.'),
  (26, 'attrezzatura', 'Perché la punta della fresa deve restare in movimento?', '["Per lucidare meglio","Per evitare calore da attrito e solchi","Per consumare meno","Non è necessario"]'::jsonb, 1, 'Fermarsi in un punto scalda e scava.'),
  (27, 'preparazione', 'Qual è la prima causa di sollevamento?', '["La lampada","Una preparazione non accurata","Il colore","La forma"]'::jsonb, 1, 'Pterigio, sebo e umidità sono i nemici dell''adesione.'),
  (28, 'preparazione', 'L''opacizzazione dell''unghia naturale serve a…', '["Assottigliarla","Togliere la lucidità","Accorciarla","Sbiancarla"]'::jsonb, 1, 'Si toglie solo la lucidità, mai spessore.'),
  (29, 'preparazione', 'L''ordine corretto è…', '["Primer → disidratante","Disidratante → primer","Solo primer","Top → primer"]'::jsonb, 1, 'Prima si disidrata, poi si applica il primer.'),
  (30, 'preparazione', 'Il primer acido è indicato soprattutto per…', '["Semipermanente","Acrilico e unghie difficili","Top coat","Rimozione"]'::jsonb, 1, 'Va usato in quantità minima e solo sulla lamina.'),
  (31, 'preparazione', 'Dopo il disidratante…', '["Tocco la lamina per controllare","Non tocco più la lamina con le dita","Lavo le mani della cliente","Applico olio"]'::jsonb, 1, 'Il sebo delle dita riduce l''adesione.'),
  (32, 'tip', 'Come scegli la misura del tip?', '["Il più piccolo possibile","Deve coprire da solco a solco","Sempre la misura 5","In base al colore"]'::jsonb, 1, 'Se sei tra due misure scegli la più grande e lima i lati.'),
  (33, 'tip', 'Con quale angolo si appoggia il tip?', '["90°","Circa 45°, poi si abbassa","0°, piatto subito","180°"]'::jsonb, 1, 'Abbassandolo lentamente l''aria esce e non si formano bolle.'),
  (34, 'tip', 'Durante il blending del tip…', '["Limo anche l''unghia naturale","Fondo solo la linea di contatto del tip","Uso la grana 80 sulla lamina","Uso acetone"]'::jsonb, 1, 'Non si lima l''unghia naturale.'),
  (35, 'tip', 'I tip "a contatto"…', '["Hanno un incavo da fondere","Non hanno incavo e non vanno fusi","Si applicano senza colla","Sono solo per i piedi"]'::jsonb, 1, 'Non c''è zona d''incavo da fondere.'),
  (36, 'cartina', 'Dove va costruito l''apex?', '["Alla cuticola","Sopra il punto di stress","Sulla punta","Ovunque"]'::jsonb, 1, 'In zona 2, sopra il punto di stress.'),
  (37, 'cartina', 'Quanto margine lasci dalla pelle in zona cuticolare?', '["Nessuno","Circa 1,5 mm","5 mm","1 cm"]'::jsonb, 1, 'Circa 1,5 mm evita contatto con la pelle e sollevamenti.'),
  (38, 'cartina', 'Cosa succede se la cartina lascia uno spazio sotto il bordo libero?', '["Niente","Il prodotto cola sotto e crea sollevamenti","L''unghia è più robusta","Si polimerizza prima"]'::jsonb, 1, 'La cartina va a filo del bordo libero.'),
  (39, 'cartina', 'Una ricostruzione piatta, senza apex…', '["È più naturale e resistente","Si rompe facilmente","Non si solleva mai","Dura di più"]'::jsonb, 1, 'Senza struttura non regge la lunghezza.'),
  (40, 'cartina', 'Quando si pizzica il gel per la curva a C?', '["Prima di stenderlo","Dopo una breve polimerizzazione (flash cure)","Dopo il top","Mai"]'::jsonb, 1, 'Per l''acrilico invece mentre non è del tutto indurito.'),
  (41, 'cartina', 'La zona 3 deve essere…', '["La più spessa","Sottilissima","Bianca","Lucida"]'::jsonb, 1, 'Sottile in zona cuticolare, struttura in zona 2.'),
  (42, 'limatura', 'Quale forma è considerata tra le più resistenti?', '["Stiletto","Squoval","Lipstick","Ballerina"]'::jsonb, 1, 'Gli angoli smussati riducono il rischio di rotture.'),
  (43, 'limatura', 'Quale forma slancia di più il dito?', '["Quadrata","Mandorla","Tonda","Squoval"]'::jsonb, 1, 'I lati convergenti allungano visivamente il dito.'),
  (44, 'limatura', 'Come si limano i lati?', '["Con la lima parallela al solco laterale","Entrando nel solco","Con la grana 80","In diagonale"]'::jsonb, 0, 'Senza entrare nel solco.'),
  (45, 'limatura', 'Il movimento corretto della lima è…', '["Avanti e indietro veloce","In una sola direzione","Circolare con forza","Casuale"]'::jsonb, 1, 'Il movimento a "sega" scalda e sfibra.'),
  (46, 'limatura', 'Da quanti punti di vista controlli la ricostruzione?', '["Solo dall''alto","Alto, profilo, fronte e sotto","Solo di profilo","Non serve controllare"]'::jsonb, 1, 'Simmetria, apex, curva a C e pulizia del bordo.'),
  (47, 'decorazioni', 'Una buona smile line è…', '["Asimmetrica","Simmetrica e con la stessa profondità sui lati","Piatta","Sfumata"]'::jsonb, 1, 'Simmetria e nettezza sono i criteri principali.'),
  (48, 'decorazioni', 'Il baby boomer è…', '["Un french con linea netta","Una sfumatura dal nude al bianco","Un tipo di gel","Una forma"]'::jsonb, 1, 'È un french sfumato.'),
  (49, 'decorazioni', 'L''incapsulato consiste nel…', '["Chiudere decorazioni tra due strati trasparenti","Mettere glitter sul top","Usare solo colori","Dipingere con il dotter"]'::jsonb, 0, 'Le decorazioni restano protette dentro il prodotto.'),
  (50, 'decorazioni', 'Lo stamping usa…', '["Una piastra incisa e un tampone","Una fresa","Un attivatore","Solo pennelli"]'::jsonb, 0, 'Il disegno viene trasferito dalla piastra.'),
  (51, 'manutenzione', 'Ogni quanto si consiglia il refill?', '["Ogni settimana","Ogni 3–4 settimane","Ogni 3 mesi","Mai"]'::jsonb, 1, 'Dopo 3–4 settimane l''apex si è spostato in avanti.'),
  (52, 'manutenzione', 'Durante il refill le parti sollevate…', '["Si coprono con prodotto nuovo","Si eliminano completamente","Si incollano","Si lasciano"]'::jsonb, 1, 'Sotto un sollevamento possono esserci umidità e batteri.'),
  (53, 'manutenzione', 'Quanto tempo serve in genere per il soak-off?', '["1 minuto","10–15 minuti","2 ore","24 ore"]'::jsonb, 1, 'Fino a circa 30 minuti per spessori alti.'),
  (54, 'manutenzione', 'L''hard gel si rimuove…', '["Con acetone","Limando, lasciando un velo sulla lamina","Strappandolo","Con acqua calda"]'::jsonb, 1, 'Non si scioglie in acetone.'),
  (55, 'manutenzione', 'Dopo la rimozione…', '["Si gratta la lamina","Si applica olio per cuticole","Si mette subito un nuovo gel senza preparare","Si lima con grana 80"]'::jsonb, 1, 'Nutrire la zona aiuta la pelle e la lamina.'),
  (56, 'problemi', 'Quale NON è una causa di sollevamento?', '["Pterigio non rimosso","Prodotto a contatto con la pelle","Bordo libero sigillato","Refill in ritardo"]'::jsonb, 2, 'Sigillare il bordo libero previene il sollevamento.'),
  (57, 'problemi', 'Il picco di calore è favorito da…', '["Strati sottili","Strati spessi e lamina assottigliata","Gel a basso calore","Lampada in low-heat"]'::jsonb, 1, 'La polimerizzazione è esotermica: strati spessi = più calore.'),
  (58, 'problemi', 'La tecnica "flash and pull" serve a…', '["Accelerare la polimerizzazione","Ridurre il calore percepito","Rimuovere il gel","Lucidare"]'::jsonb, 1, 'Si toglie la mano dalla lampada qualche secondo e la si rimette.'),
  (59, 'problemi', 'Le grinze sul gel indicano di solito…', '["Strato troppo spesso polimerizzato solo in superficie","Troppo primer","Lima sbagliata","Smile line storta"]'::jsonb, 0, 'Strati sottili e tempi corretti risolvono il problema.'),
  (60, 'problemi', 'Un gel sotto-polimerizzato aumenta il rischio di…', '["Ingiallimento soltanto","Allergia","Unghie più dure","Nessun problema"]'::jsonb, 1, 'Il monomero non reagito sensibilizza la pelle.'),
  (61, 'problemi', 'Una rottura in zona 2 dipende spesso da…', '["Apex assente o mal posizionato","Troppo olio","Colore scuro","Top lucido"]'::jsonb, 0, 'La struttura deve reggere il punto di stress.'),
  (62, 'professione', 'Cosa NON serve nella scheda cliente?', '["Allergie","Farmaci e patologie","Il colore preferito dell''auto","Consenso privacy"]'::jsonb, 2, 'La scheda raccoglie dati utili alla sicurezza del servizio.'),
  (63, 'professione', 'Quale consiglio dai dopo il trattamento?', '["Usare le unghie per aprire le lattine","Olio per cuticole ogni giorno e guanti per i lavori domestici","Staccare da sola il prodotto","Saltare il refill"]'::jsonb, 1, 'Cura quotidiana e protezione allungano la durata.'),
  (64, 'professione', 'Prezzo indicativo di un refill in Italia?', '["5 €","20–35 €","150 €","300 €"]'::jsonb, 1, 'Valori indicativi da articoli recenti; variano per zona.'),
  (65, 'professione', 'Nelle gare i giudici valutano soprattutto…', '["Il prezzo","Struttura, simmetria, pulizia e smile line","La marca dei prodotti","La velocità di pagamento"]'::jsonb, 1, 'Apex, curva a C, simmetria e pulizia sono decisivi.'),
  (66, 'onicofagia', 'Quale situazione è una controindicazione su unghie rosicchiate?', '["Unghie corte","Presenza di pus e gonfiore","Cuticole secche","Lamina sottile"]'::jsonb, 1, 'Infezione o infiammazione richiedono il medico, non una ricostruzione.'),
  (67, 'onicofagia', 'Perché si tira la cartina verso il basso su un''unghia rosicchiata?', '["Per risparmiare prodotto","Per spingere indietro la pelle rialzata e fare spazio all''allungamento","Per accorciare il letto","Per evitare il top"]'::jsonb, 1, 'Crea spazio per l''allungamento davanti all''unghia.'),
  (68, 'onicofagia', 'La causa più frequente della coilonichia (unghia a cucchiaio) è:', '["Carenza di ferro","Trauma da lima","Smalto scuro","Acetone"]'::jsonb, 0, 'Se compare da poco, si consiglia un controllo medico.'),
  (69, 'onicofagia', 'Con un''unghia ski-jump, cosa si fa prima di applicare il tip?', '["Si allunga di più","Si riduce la lunghezza naturale","Si lucida","Si applica il top"]'::jsonb, 1, 'Altrimenti il tip segue la curva verso l''alto.'),
  (70, 'onicofagia', 'Su un''unghia a pinza dolorante l''onicotecnica:', '["Accentua la curva C","Fa il pinching","Indirizza a medico o podologo","Applica acrilico spesso"]'::jsonb, 2, 'La deformità comprime i tessuti: non si forza.'),
  (71, 'onicofagia', 'Su unghie grasse il ritiro del gel è legato soprattutto a:', '["Lampada nuova","Olio residuo sulla lamina","Colori chiari","Cartine di carta"]'::jsonb, 1, 'Disidratante, primer adatto e nuovo sgrassaggio prima della base.'),
  (72, 'cover-colori', 'A cosa serve principalmente il gel cover?', '["Lucidare","Allungare otticamente il letto ungueale e coprire imperfezioni","Sgrassare","Ammorbidire le cuticole"]'::jsonb, 1, 'È un costruttore pigmentato color pelle.'),
  (73, 'cover-colori', 'Perché i gel molto pigmentati vanno stesi sottili?', '["Per risparmiare","Perché il pigmento assorbe la luce e gli strati profondi polimerizzano male","Per un effetto opaco","Non serve"]'::jsonb, 1, 'Con strati spessi la parte profonda resta sotto-polimerizzata.'),
  (74, 'cover-colori', 'Il primo strato di un colore appare striato. È:', '["Un difetto del prodotto","Normale: il secondo strato uniforma","Segno di lampada rotta","Da rimuovere sempre"]'::jsonb, 1, 'Molti colori coprono al secondo strato sottile.'),
  (75, 'cover-colori', 'Quale NON è una causa di ritiro dai bordi?', '["Olio sulla lamina","Primer ancora umido sui lati","Lampada non compatibile","Uso di una cartina di carta"]'::jsonb, 3, 'Le prime tre sono cause tipiche di ritiro.'),
  (76, 'cover-colori', 'Il colore complementare del giallo, che lo neutralizza, è:', '["Viola","Verde","Arancio","Rosso"]'::jsonb, 0, 'Sono opposti sul cerchio cromatico.'),
  (77, 'cover-colori', 'Per un french con camouflage, la sequenza consigliata è:', '["Bianco prima, cover dopo","Cover prima, poi la smile line","Solo top","Solo bianco"]'::jsonb, 1, 'Si disegna la smile line sopra il cover.'),
  (78, 'piedi', 'Rispetto alle mani, le unghie dei piedi crescono:', '["Più velocemente","Alla stessa velocità","A meno della metà della velocità","Non crescono"]'::jsonb, 2, 'Circa 1,6 contro 3,5 mm al mese in uno studio su giovani adulti.'),
  (79, 'piedi', 'Per prevenire l''unghia incarnita si taglia:', '["A punta","Molto corta e tonda","Dritta, angoli appena smussati","Scavando i lati"]'::jsonb, 2, 'Indicazione dei dermatologi (AAD).'),
  (80, 'piedi', 'Un''unghia gialla, ispessita e friabile:', '["Si copre con gel colorato","Si lima fino ad assottigliarla","Non si tratta: si consiglia medico o podologo","Si ricostruisce in acrilico"]'::jsonb, 2, 'Possibile micosi: controindicazione.'),
  (81, 'piedi', 'Chi tratta le unghie incarnite in Italia?', '["L''estetista","L''onicotecnica","Il podologo (o il medico)","Chiunque abbia una lima"]'::jsonb, 2, 'Il podologo è una professione sanitaria (DM 666/1994).'),
  (82, 'piedi', 'Cliente diabetica con una ferita al piede che non guarisce:', '["Pedicure con lama","Pediluvio caldo","Niente servizio, invio a medico o podologo","Semipermanente rinforzato"]'::jsonb, 2, 'Rischio di lesioni non percepite e infezioni.'),
  (83, 'piedi', 'La L. 1/1990 esclude dall''attività di estetista:', '["La manicure estetica","Le prestazioni con finalità terapeutica","Il trucco","Il massaggio estetico"]'::jsonb, 1, 'L''estetista lavora a scopo estetico.'),
  (84, 'arte-gare', 'Su cosa si applica la polvere chrome?', '["Gel colorato non polimerizzato","Top no-wipe polimerizzato","Base appiccicosa","Lamina nuda"]'::jsonb, 1, 'Poi si sigillano i bordi e si mette il top.'),
  (85, 'arte-gare', 'Nel cat-eye il magnete si usa:', '["Dopo il top","Prima di polimerizzare lo strato magnetico","Dopo la polimerizzazione","Non serve"]'::jsonb, 1, 'Le particelle si orientano finché il gel è fluido.'),
  (86, 'arte-gare', 'Nel one-stroke, per iniziare, il pennello piatto si carica:', '["Con un solo colore","Circa metà e metà con due colori","Fino alla ghiera","Asciutto"]'::jsonb, 1, 'Il colore non deve entrare nella ghiera.'),
  (87, 'arte-gare', 'In gara, il gel non polimerizzato a fine prova comporta:', '["−5 punti","Nessuna penalità","Squalifica","Un bonus"]'::jsonb, 2, 'È una regola tipica dei regolamenti Nailympia.'),
  (88, 'arte-gare', 'La "vista a tunnel" valuta soprattutto:', '["La smile line","La curva C","Il colore","La lucentezza"]'::jsonb, 1, 'Si guarda l''unghia dalla punta.'),
  (89, 'arte-gare', 'In un''unghia con decorazione incapsulata, l''apex:', '["Non serve","Si costruisce sopra la decorazione","Va alla cuticola","Si sostituisce con glitter"]'::jsonb, 1, 'La struttura deve restare corretta.');
